          github-token: ${{ secrets.GITHUB_TOKEN }}
          run-id: ${{ github.event.workflow_run.id }}

      - name: Post comment on PR
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');

            const pullRequests = context.payload.workflow_run.pull_requests;
            let prNumber;
            if (pullRequests && pullRequests.length > 0) {
              prNumber = pullRequests[0].number;
            } else {
              try {
                prNumber = parseInt(fs.readFileSync('pr_number', 'utf8').trim());
              } catch (e) {
                console.log('No PR number found, skipping comment.');
                return;
              }
            }
            if (!prNumber || isNaN(prNumber)) {
              console.log('No valid PR number found, skipping comment.');
              return;
            }

            const runUrl = `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${{ github.event.workflow_run.id }}`;

            let errorDetails = '';
            try {
              const raw = fs.readFileSync('error_output', 'utf8').trim();
              if (raw) {
                errorDetails = raw.length > 30000 ? raw.substring(0, 30000) + '\n\n... (truncated)' : raw;
              }
            } catch (e) {}

            const detailsSection = errorDetails
              ? `\n<details>\n<summary>Broken links found by Lychee</summary>\n\n${errorDetails}\n\n</details>\n`
              : '';

            const commentBody = `
            ## ❌ Link Check Failed

            🔗 [View workflow run logs](${runUrl})
            ${detailsSection}
            ### Common fixes:

            1. **Typo in URL** - Check for spelling mistakes in the link
            2. **Outdated link** - The page may have moved or been deleted
            3. **Relative path issue** - Ensure relative links use the correct path
            4. **External site down** - If the external site is temporarily down, you can add it to \`brev/.lycheeignore\`

            ### To test links locally:

            \`\`\`bash
            ./brev/test-links.bash .
            \`\`\`

            📚 [Lychee documentation](https://github.com/lycheeverse/lychee)
            `.replace(/^ {12}/gm, '').trim();

            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber
            });

            const botComment = comments.find(comment =>
              comment.user.type === 'Bot' &&
              comment.body.includes('Link Check Failed')
            );

            if (botComment) {
              // Update existing comment
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: botComment.id,
                body: commentBody
              });
              console.log(`Updated existing comment on PR #${prNumber}`);
            } else {
              // Create new comment
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: commentBody
              });
              console.log(`Created comment on PR #${prNumber}`);
            }

name: PR Comment on Git LFS Check

on:
  workflow_run:
    workflows: ["Test Git LFS"]
    types: [completed]

permissions:
  pull-requests: write
  actions: read

jobs:
  comment:
    runs-on: ubuntu-latest
    if: >-
      github.event.workflow_run.conclusion == 'failure' &&
      (github.event.workflow_run.pull_requests[0] || startsWith(github.event.workflow_run.head_branch, 'pull-request/'))

    steps:
      - name: Download PR comment data
        uses: actions/download-artifact@v4
        with:
          name: pr-comment-data
          github-token: ${{ secrets.GITHUB_TOKEN }}
          run-id: ${{ github.event.workflow_run.id }}

      - name: Post comment on PR
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');

            const pullRequests = context.payload.workflow_run.pull_requests;
            let prNumber;
            if (pullRequests && pullRequests.length > 0) {
              prNumber = pullRequests[0].number;
            } else {
              try {
                prNumber = parseInt(fs.readFileSync('pr_number', 'utf8').trim());
              } catch (e) {
                console.log('No PR number found, skipping comment.');
                return;
              }
            }
            if (!prNumber || isNaN(prNumber)) {
              console.log('No valid PR number found, skipping comment.');
              return;
            }

            const errorType = fs.readFileSync('error_type', 'utf8').trim();
            const errorFiles = fs.readFileSync('error_files', 'utf8').trim();

            if (!errorType) {
              console.log('No error type found, skipping comment.');
              return;
            }

            const runUrl = `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${{ github.event.workflow_run.id }}`;

            let commentBody;
            if (errorType === 'subdir_gitattributes') {
              const fileList = errorFiles.split('\n').map(f => f.trim()).filter(f => f).map(f => '- `' + f + '`').join('\n');
              commentBody = `
              ## ❌ Git LFS Check Failed

              🔗 [View workflow run logs](${runUrl})

              **Found \`.gitattributes\` file(s) in subdirectories.** Only the top-level \`.gitattributes\` should be used for LFS configuration.

              <details>
              <summary>Files to remove</summary>

              ${fileList}

              </details>

              ### How to fix:

              \`\`\`bash
              git rm <path/to/.gitattributes>
              git commit -m "Remove subdirectory .gitattributes"
              \`\`\`

              📚 [Git LFS documentation](https://git-lfs.com/)
              `.replace(/^ {14}/gm, '').trim();
            } else if (errorType === 'not_lfs_tracked') {
              commentBody = `
              ## ❌ Git LFS Check Failed

              🔗 [View workflow run logs](${runUrl})

              **The following files should be tracked by Git LFS but are not:**

              <details>
              <summary>Files not tracked by LFS</summary>

              ${errorFiles}

              </details>

              ### How to fix:

              \`\`\`bash
              # For each file listed above:
              git rm --cached <file>
              git add <file>
              git commit -m "Track file with Git LFS"
              \`\`\`

              Make sure Git LFS is installed locally (\`git lfs install\`) before running these commands.

              📚 [Git LFS documentation](https://git-lfs.com/)
              `.replace(/^ {14}/gm, '').trim();
            } else {
              console.log(`Unknown error type: ${errorType}, skipping comment.`);
              return;
            }

            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber
            });

            const botComment = comments.find(comment =>
              comment.user.type === 'Bot' &&
              comment.body.includes('Git LFS Check Failed')
            );

            if (botComment) {
              // Update existing comment
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: botComment.id,
                body: commentBody
              });
              console.log(`Updated existing comment on PR #${prNumber}`);
            } else {
              // Create new comment
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: commentBody
              });
              console.log(`Created comment on PR #${prNumber}`);
            }

#!/usr/bin/env python3
"""Restart the current container's persistent Docker Compose siblings."""

import http.client
import json
import os
import socket
import sys
import urllib.parse


DOCKER_SOCKET = "/var/run/docker.sock"
NON_PERSISTENT_SERVICES = {"base"}


class UnixHTTPConnection(http.client.HTTPConnection):
    """An HTTP connection transported over a Unix-domain socket."""

    def __init__(self, socket_path):
        super().__init__("localhost")
        self.socket_path = socket_path

    def connect(self):
        self.sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        self.sock.connect(self.socket_path)


def docker_request(method, path):
    """Send one request to the Docker Engine API and return its body."""
    connection = UnixHTTPConnection(DOCKER_SOCKET)
    try:
        connection.request(method, path)
        response = connection.getresponse()
        body = response.read()
    finally:
        connection.close()

    if response.status >= 300:
        detail = body.decode("utf-8", errors="replace")
        raise RuntimeError(
            f"Docker API {method} {path} returned {response.status}: {detail}"
        )
    return body


def container_details(container_name):
    """Return Docker metadata for a container name or ID."""
    container_path = urllib.parse.quote(container_name, safe="")
    return json.loads(docker_request("GET", f"/containers/{container_path}/json"))


def main():
    if not os.path.exists(DOCKER_SOCKET):
        print(f"Docker socket not found at {DOCKER_SOCKET}")
        return 0

    current = container_details(socket.gethostname())
    labels = current.get("Config", {}).get("Labels", {}) or {}
    project = labels.get("com.docker.compose.project")
    current_service = labels.get("com.docker.compose.service")
    if not project or not current_service:
        raise RuntimeError(
            "Current container has no Docker Compose project/service labels"
        )

    filters = json.dumps({"label": [f"com.docker.compose.project={project}"]})
    query = urllib.parse.urlencode({"all": "1", "filters": filters})
    containers = json.loads(docker_request("GET", f"/containers/json?{query}"))

    siblings = []
    for container in containers:
        sibling_labels = container.get("Labels", {}) or {}
        service = sibling_labels.get("com.docker.compose.service")
        one_off = sibling_labels.get("com.docker.compose.oneoff", "False")
        if (
            not service
            or service == current_service
            or service in NON_PERSISTENT_SERVICES
        ):
            continue
        if one_off.lower() == "true":
            continue
        siblings.append((service, container["Id"]))

    failed = False
    for service, container_id in sorted(siblings):
        try:
            docker_request("POST", f"/containers/{container_id}/restart?t=10")
        except (OSError, RuntimeError) as error:
            print(
                f"Error: Could not restart Compose service {project}/{service}: "
                f"{error}",
                file=sys.stderr,
            )
            failed = True
        else:
            print(f"Restarted Compose service {project}/{service}")

    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Adapt an ACH Docker Compose file for rootless Podman."""

import glob
import os
import re
import stat
import subprocess
import sys

try:
    import yaml
except ImportError:
    print(
        "Error: PyYAML is required to prepare a Podman Compose file. "
        "Install it with 'python3 -m pip install PyYAML'.",
        file=sys.stderr,
    )
    raise SystemExit(1)


GPU_SERVICES = {"base", "jupyter", "nsight", "nsys", "ncu"}
NVIDIA_CONTROL_DEVICES = (
    "/dev/nvidiactl",
    "/dev/nvidia-modeset",
    "/dev/nvidia-uvm",
    "/dev/nvidia-uvm-tools",
)
NVIDIA_FALLBACK_LIBRARIES = (
    ("libcuda", "libcuda.so.1"),
    ("libnvidia-ml", "libnvidia-ml.so.1"),
    ("libnvidia-ptxjitcompiler", "libnvidia-ptxjitcompiler.so.1"),
    ("libnvidia-nvvm", "libnvidia-nvvm.so.4"),
)
NVIDIA_LIBRARY_DIRECTORIES = ("/usr/lib/*-linux-gnu", "/usr/lib64")
NVIDIA_LIBRARY_GLOBS = (
    "libcuda.so.*",
    "libcudadebugger.so.*",
    "libnvidia-*.so.*",
    "libnvcuvid.so.*",
    "libnvoptix.so.*",
    "libGLX_nvidia.so.*",
    "libEGL_nvidia.so.*",
    "libGLES*_nvidia.so.*",
    "vdpau/libvdpau_nvidia.so.*",
)


def strip_podman_incompatible(value):
    """Remove Compose keys unsupported by the rootless Podman setup."""
    if isinstance(value, dict):
        for key in ("privileged", "ulimits", "deploy"):
            value.pop(key, None)
        volumes = value.get("volumes")
        if isinstance(volumes, list):
            value["volumes"] = [
                mount
                for mount in volumes
                if not (
                    isinstance(mount, str)
                    and mount.split(":", 1)[0] == "/var/run/docker.sock"
                )
            ]
        for child in value.values():
            strip_podman_incompatible(child)
    elif isinstance(value, list):
        for child in value:
            strip_podman_incompatible(child)


def nvidia_container_libraries():
    """Ask NVIDIA Container Toolkit for the driver library set when available."""
    try:
        result = subprocess.run(
            ["nvidia-container-cli", "list", "--libraries"],
            capture_output=True,
            check=True,
            text=True,
            timeout=30,
        )
    except (FileNotFoundError, subprocess.SubprocessError):
        return []
    return [line for line in result.stdout.splitlines() if line.startswith("/")]


def elf_soname(path):
    """Return an ELF library's declared soname, with a symlink fallback."""
    try:
        result = subprocess.run(
            ["readelf", "-d", path],
            capture_output=True,
            check=True,
            text=True,
            timeout=10,
        )
        match = re.search(r"\(SONAME\).*\[([^]]+)]", result.stdout)
        if match:
            return match.group(1)
    except (FileNotFoundError, subprocess.SubprocessError):
        pass

    basename = os.path.basename(path)
    for library, soname in NVIDIA_FALLBACK_LIBRARIES:
        if basename.startswith(f"{library}.so."):
            return soname

    real_path = os.path.realpath(path)
    candidates = []
    for candidate in glob.glob(f"{os.path.dirname(path)}/*.so*"):
        if os.path.islink(candidate) and os.path.realpath(candidate) == real_path:
            name = os.path.basename(candidate)
            if ".so." in name:
                candidates.append(name)
    return min(candidates, key=len) if candidates else basename


def find_nvidia_mounts():
    """Return host NVIDIA files, library directories, and required soname links."""
    paths = []
    if os.path.isfile("/usr/bin/nvidia-smi"):
        paths.append("/usr/bin/nvidia-smi")

    paths.extend(nvidia_container_libraries())
    if len(paths) == (1 if "/usr/bin/nvidia-smi" in paths else 0):
        for directory in NVIDIA_LIBRARY_DIRECTORIES:
            for pattern in NVIDIA_LIBRARY_GLOBS:
                paths.extend(glob.glob(f"{directory}/{pattern}"))

    files = sorted(
        {path for path in paths if os.path.isfile(path) and not os.path.islink(path)}
    )
    mounts = [f"{path}:{path}:ro" for path in files]
    directories = sorted(
        {os.path.dirname(path) for path in files if path != "/usr/bin/nvidia-smi"}
    )
    links = [
        (path, elf_soname(path))
        for path in files
        if path != "/usr/bin/nvidia-smi"
    ]
    return mounts, directories, links


def find_nvidia_devices():
    """Return allocated GPU devices plus the available control devices."""

    def is_character_device(path):
        try:
            return stat.S_ISCHR(os.stat(path).st_mode)
        except OSError:
            return False

    gpu_devices = sorted(
        path
        for path in glob.glob("/dev/nvidia[0-9]*")
        if path.removeprefix("/dev/nvidia").isdigit() and is_character_device(path)
    )
    if not gpu_devices:
        return []
    return gpu_devices + [
        path for path in NVIDIA_CONTROL_DEVICES if is_character_device(path)
    ]


def replace_repo_volume(data, repo_root):
    """Bind one checkout as the container repository."""
    volume_name = "accelerated-computing-hub"
    bind_mount = f"{repo_root}:/accelerated-computing-hub"
    for service in (data.get("services") or {}).values():
        volumes = service.get("volumes") or []
        service["volumes"] = [
            bind_mount if item == f"{volume_name}:/accelerated-computing-hub" else item
            for item in volumes
        ]
        environment = service.get("environment") or {}
        if isinstance(environment, dict):
            environment.update({"ACH_USER": "root", "ACH_UID": "0", "ACH_GID": "0"})
            service["environment"] = environment

    volumes = data.get("volumes")
    if isinstance(volumes, dict):
        volumes.pop(volume_name, None)


def add_rootless_gpu_access(data):
    """Pass the allocated GPU and host driver libraries through to Podman."""
    devices = find_nvidia_devices()
    if not devices:
        return

    mounts, library_directories, library_links = find_nvidia_mounts()
    library_links = " ".join(
        f"{path}:{soname}" for path, soname in library_links
    )

    for service_name, service in (data.get("services") or {}).items():
        if service_name not in GPU_SERVICES:
            continue

        service_devices = service.get("devices") or []
        service["devices"] = service_devices + [
            device for device in devices if device not in service_devices
        ]

        volumes = service.get("volumes") or []
        service["volumes"] = volumes + [
            mount for mount in mounts if mount not in volumes
        ]

        environment = service.get("environment") or {}
        if isinstance(environment, dict):
            environment["ACH_ROOTLESS_PODMAN"] = "1"
            environment["ACH_NVIDIA_LIBRARY_LINKS"] = library_links
            if library_directories:
                environment["ACH_NVIDIA_LIB_DIRS"] = ":".join(library_directories)
            service["environment"] = environment


def use_host_network(data, all_services=False):
    """Avoid rootless veth creation where the host cannot create one."""
    services = data.get("services") or {}
    selected = services.values() if all_services else (services.get("base"),)
    for service in selected:
        if service is None:
            continue
        service["network_mode"] = "host"
        service.pop("ports", None)

    if all_services:
        jupyter = services.get("jupyter")
        if jupyter is not None:
            environment = jupyter.get("environment") or {}
            if isinstance(environment, dict):
                environment = environment.copy()
                # All services share localhost; socat cannot bind ports already
                # owned by the Streamers and Compose DNS is unavailable.
                environment.update(
                    {
                        "ACH_PORT_FORWARDS": "",
                        "JUPYTER_IP": "127.0.0.1",
                    }
                )
                for name in (
                    "JUPYTER_HTTPS_CERT",
                    "JUPYTER_HTTPS_KEY",
                    "JUPYTER_HOST",
                    "NSYS_HTTP_URL",
                    "SELKIES_ENABLE_HTTPS",
                ):
                    if name in os.environ:
                        environment[name] = os.environ[name]
                jupyter["environment"] = environment

        for service_name in ("nsight", "nsys", "ncu"):
            service = services.get(service_name)
            if service is None:
                continue
            environment = service.get("environment") or {}
            if not isinstance(environment, dict):
                continue
            environment = environment.copy()
            environment.update(
                {
                    "HOST_IP": "127.0.0.1",
                    "SELKIES_ADDR": "127.0.0.1",
                    "SELKIES_TURN_HOST": "127.0.0.1",
                }
            )
            for name in (
                "SELKIES_ENABLE_HTTPS",
                "SELKIES_HTTPS_CERT",
                "SELKIES_HTTPS_KEY",
            ):
                if name in os.environ:
                    environment[name] = os.environ[name]
            if service_name == "ncu":
                # Host networking also shares the HTTP port and abstract X
                # socket namespace. Keep NCU separate from NSYS.
                environment.update(
                    {"DISPLAY": ":5", "HTTP_PORT": "8081", "TURN_PORT": "3479"}
                )
            service["environment"] = environment


def prepare(source, destination, repo_root="", bind_repo=False):
    """Write a Podman-compatible copy of source to destination."""
    with open(source, "r", encoding="utf-8") as handle:
        data = yaml.safe_load(handle)

    strip_podman_incompatible(data)
    use_host_network(
        data,
        all_services=os.environ.get("ACH_PODMAN_HOST_NETWORK") == "1",
    )
    if bind_repo and repo_root:
        replace_repo_volume(data, repo_root)
    add_rootless_gpu_access(data)

    with open(destination, "w", encoding="utf-8") as handle:
        yaml.safe_dump(data, handle, default_flow_style=False, sort_keys=False)


def main():
    if len(sys.argv) != 5:
        raise SystemExit(f"Usage: {sys.argv[0]} SOURCE DESTINATION REPO_ROOT BIND_REPO")
    source, destination, repo_root, bind_repo = sys.argv[1:]
    prepare(source, destination, repo_root, bind_repo == "1")


if __name__ == "__main__":
    main()
